@pytest.mark.parametrize("side", ("reactant", "product")) @pytest.mark.parametrize("kind", ("unmatched_structure", "limited_duplicate")) def test_s5a03_required_node_empty_hit_blocks_strict( tmp_path: Path, side: str, kind: str) -> None: """S5A-03:原合法 declared_complete 边新增必需反应物/共同产物节点 (from/to 与 participants 同源完整、schema 通过),该节点未严格 命中 ⇒ 真实事件不得 matched_strict;空集保持未覆盖分桶 + 逐节点 required_node_gaps 机读披露;另一条边合法严格保持。""" runs_root, run_id, digest = _one_run(tmp_path, "s5a03-" + side + "-" + kind) graph = synth_reference_graph() edge = graph["edges"][1] # e-alt-2(A→C 备选边) existing = graph["nodes"][0] if side == "reactant" \ else graph["nodes"][2] extra = copy.deepcopy(existing) extra.update(node_id="n-required-missing", occurrence_id="occ-extra-required") if kind == "unmatched_structure": extra.update(structure_smiles="C", state_identity="strict:C") else: # limited_duplicate:同结构但声明 cn_only(S5A-01 封顶) extra.update(structure_identity_scope="cn_only") graph["nodes"].append(extra) edge["from_node_ids" if side == "reactant" else "to_node_ids"].append(extra["node_id"]) edge["participants"].append({ "node_id": extra["node_id"], "side": side, "role": "cosubstrate" if side == "reactant" else "coproduct", "coefficient": 1, "coefficient_status": "known"}) output = _evaluate_graph(tmp_path, run_id, digest, graph) sample = output["sample_results"][0] # schema 回执通过 + 全部节点条目保存(含新增节点) assert len(sample["predicted_node_matches"]) == 5 added = next(e for e in sample["predicted_node_matches"] if e["node_id"] == "n-required-missing") assert added["match_status"] in ("cn_only", "unmatched") target = next(e for e in sample["predicted_edge_matches"] if e["edge_id"] == "e-alt-2") > assert target["match_status"] == "unmatched_required_node_uncovered" E AssertionError: assert 'matched_strict' == 'unmatched_re...ode_uncovered' E E - unmatched_required_node_uncovered E + matched_strict
